@if($latestInvitation?->isUsable())
@if($latestInvitation->encrypted_token)<button id="copy-invitation-link" class="btn btn-outline-brand" type="button" data-link="{{route('portal.invitation.show',$latestInvitation->encrypted_token)}}" hidden>Copy invitation link</button>@endif
