@if($client->portalAccount?->enabled)<div class="alert alert-success"><strong>Active.</strong> {{$client->portalAccount->email}} <span aria-hidden="true">&mdash;</span> Last login: {{$client->portalAccount->last_login_at?->format('M j, Y g:i A') ?? 'Never'}}</div><div class="d-flex flex-wrap gap-2"><form method="post" action="{{route('admin.portal-access.store',$client)}}">@csrf<button class="btn btn-outline-brand" type="submit">Open client portal as administrator</button></form><form method="post" action="{{route('admin.portal-access.reset',$client)}}" onsubmit="return confirm('Disable current portal access and send a new password setup invitation?');">@csrf<button class="btn btn-brand" type="submit">Reset portal access</button></form><form method="post" action="{{route('admin.portal-access.revoke',$client)}}" onsubmit="return confirm('Revoke portal access? No new invitation will be sent.');">@csrf @method('DELETE')<button class="btn btn-outline-danger" type="submit">Revoke portal access</button></form></div>
@elseif($latestInvitation && $latestInvitation->isUsable())<div class="alert alert-info"><strong>Invitation pending.</strong> Sent to {{$latestInvitation->email}}; expires {{$latestInvitation->expires_at->format('M j, Y g:i A')}}.</div><div class="d-flex gap-2"><form method="post" action="{{route('admin.clients.portal-invitations.store',$client)}}">@csrf<button class="btn btn-brand">Resend invitation</button></form><form method="post" action="{{route('admin.clients.portal-invitations.destroy',[$client,$latestInvitation])}}">@csrf @method('DELETE')<button class="btn btn-outline-danger">Revoke invitation</button></form></div>
