</div></div></section>
@push('scripts')<script>{const button=document.getElementById('copy-invitation-link');if(button){const resend=document.querySelector('form[action$="/portal-invitations"]');resend?.parentElement.prepend(button);button.hidden=false;button.addEventListener('click',async()=>{const label=button.textContent;try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(button.dataset.link);else{const area=document.createElement('textarea');area.value=button.dataset.link;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}button.textContent='Copied!';setTimeout(()=>button.textContent=label,2000)}catch{window.prompt('Copy this invitation link:',button.dataset.link)}})}}</script>@endpush
